#define R_PIN 9
#define G_PIN 10
#define B_PIN 11

int r = 0, g = 0, b = 0;

void setup() {
  pinMode(R_PIN, OUTPUT);
  pinMode(G_PIN, OUTPUT);
  pinMode(B_PIN, OUTPUT);
}

void loop() {
  fadeToColor(255, 0, 0);   // Красный
  fadeToColor(0, 255, 0);   // Зелёный
  fadeToColor(0, 255, 255); // Голубой
  fadeToColor(255, 0, 0);   // Красный (замыкание цикла)
}

void fadeToColor(int tr, int tg, int tb) {
  while (r != tr || g != tg || b != tb) {
    if (r < tr) r++; else if (r > tr) r--;
    if (g < tg) g++; else if (g > tg) g--;
    if (b < tb) b++; else if (b > tb) b--;
    analogWrite(R_PIN, r);
    analogWrite(G_PIN, g);
    analogWrite(B_PIN, b);
    delay(20);
  }
}
